/// The published variables (`sce:direction="out"`) as one owned value, in
/// declaration order.
#[derive(Debug, Clone, PartialEq)]
#[allow(non_snake_case)]
pub struct StaticUnionData {
    pub built: StaticUnionUnionShapeUnion,
    pub kept: Option<StaticUnionUnionShapeUnion>,
    pub last_kind: StaticUnionKindEnum,
    pub radius: u16,
    pub width: u16,
    pub height: u16,
    pub labels: u32,
    pub points: u32,
    pub dots: u32,
    pub many_radius: u16,
    pub many_width: u16,
    pub many_shapes: u32,
    pub maybe_width: u16,
    pub refusals: u32,
    pub lifted: Option<StaticUnionUnionShapeUnion>,
    pub lift_why: Option<StaticUnionLiftRefusalRecord>,
}

/// What a host observes: the full active configuration — every active state,
/// each region of a `<parallel>` included — and the published variables,
/// taken together between two host calls, which is a macrostep boundary (W3C
/// SCXML Appendix D). `truncated` is `true` when that macrostep was stopped at
/// the microstep ceiling, so the configuration is not a stable one. Owned: a
/// host holding one keeps what it saw whatever the machine does next.
#[derive(Debug, Clone, PartialEq)]
pub struct StaticUnionSnapshot {
    pub configuration: StaticUnionConfiguration,
    pub data: StaticUnionData,
    pub truncated: bool,
}

/// The snapshot of a running machine, as an extension of the runtime's
/// `Engine` (a foreign type, so a local trait — the `Inject` shape).
pub trait StaticUnionObserve {
    /// The machine as the host sees it now: one [`StaticUnionSnapshot`],
    /// never a state between two microsteps.
    fn snapshot(&self) -> StaticUnionSnapshot;
}

impl StaticUnionObserve for Engine<StaticUnionPolicy> {
    fn snapshot(&self) -> StaticUnionSnapshot {
        let policy = self.policy();
        StaticUnionSnapshot {
            configuration: self.get_active_states(),
            data: StaticUnionData {
                built: policy.built.clone(),
                kept: policy.kept.clone(),
                last_kind: policy.last_kind,
                radius: policy.radius,
                width: policy.width,
                height: policy.height,
                labels: policy.labels,
                points: policy.points,
                dots: policy.dots,
                many_radius: policy.many_radius,
                many_width: policy.many_width,
                many_shapes: policy.many_shapes,
                maybe_width: policy.maybe_width,
                refusals: policy.refusals,
                lifted: policy.lifted.clone(),
                lift_why: policy.lift_why.clone(),
            },
            truncated: self.last_macrostep_truncated(),
        }
    }
}

